"""Cross-check the diagnostic basis against an independent brute force.

The brute force is derived directly from the specification text, using the
program's own runs only as the raw material (as the public checker does).
"""
import itertools, json, subprocess, sys, random
sys.path.insert(0, '/workspace/tests')
from harness import run, prof, query, rec, Checks

c = Checks()

def signature(runres):
    return runres['rcode'], frozenset((r['owner'], r['type'], r['data'])
                                       for r in runres['answer'])

def brute(doc, runs, out):
    """Return the optimal (cost, count) computed by exhaustive enumeration."""
    costs = {q['id']: q['cost'] for q in doc['queries']}
    pids = [p['id'] for p in doc['profiles']]
    qids = [q['id'] for q in doc['queries']]
    matrix = {(r['query'], r['profile']): signature(r) for r in runs}
    pairs = []
    for pa, pb in itertools.combinations(pids, 2):
        diff = {q for q in qids if matrix[q, pa] != matrix[q, pb]}
        if diff:
            pairs.append((pa, pb, diff))
    if not pairs:
        return [], 0, 0
    best = None
    n = len(qids)
    subsets = 0
    for size in range(1, n + 1):
        for combo in itertools.combinations(qids, size):
            selected = set(combo)
            if any(not (d & selected) for _, _, d in pairs):
                continue
            subsets += 1
            total = sum(costs[q] for q in combo)
            key = (total, len(combo))
            if best is None or key < best[0]:
                best = (key, combo)
    assert best is not None
    return sorted(best[1]), best[0][0], best[0][1]

def verify_doc(name, doc):
    got = c.expect_valid(name, doc)
    if not isinstance(got, dict):
        return False
    diag = got['diagnostic']
    basis, cost, count = brute(doc, got['runs'], got)
    ok = (diag['cost'] == cost and diag['count'] == count)
    if not ok:
        c.check(name + ' optimum', False,
                'got cost=%s count=%s basis=%s; brute cost=%s count=%s basis=%s'
                % (diag['cost'], diag['count'], diag['basis'], cost, count, basis))
        return False
    # the returned basis must distinguish every non-equivalent pair
    matrix = {(r['query'], r['profile']): signature(r) for r in got['runs']}
    pids = sorted(p['id'] for p in doc['profiles'])
    qids = [q['id'] for q in doc['queries']]
    basis_set = set(diag['basis'])
    pairs_ok = True
    for pa, pb in itertools.combinations(pids, 2):
        diff = {q for q in qids if matrix[q, pa] != matrix[q, pb]}
        if diff and not (diff & basis_set):
            pairs_ok = False
    costs = {q['id']: q['cost'] for q in doc['queries']}
    accounting = (sum(costs[q] for q in diag['basis']) == diag['cost']
                  and len(diag['basis']) == diag['count']
                  and diag['basis'] == sorted(basis_set))
    # equivalence classes must group profiles with identical signatures
    groups = {}
    for pid in pids:
        groups.setdefault(tuple(matrix[(q, pid)] for q in sorted(qids)), []).append(pid)
    expected_classes = sorted(sorted(v) for v in groups.values())
    classes_ok = (expected_classes == diag['equivalence'])
    c.check(name, pairs_ok and accounting and classes_ok, '')
    return pairs_ok and accounting and classes_ok

# --------- a case where the greedy answer is wrong but the optimum is not ---------
# Two pairs are separated only by expensive queries; a greedy by-cost pick of
# the cheapest query overall would leave the second pair undistinguished.
doc = {'zones': [
