    p = run(doc)
    if p[0] != 0 or not p[1].startswith(b'{"runs'):
        c.check('fuzz trial %d valid' % trial, False, p[1][:100])
        continue
    parsed = json.loads(p[1])
    if check_invariants('fuzz trial %d' % trial, doc, parsed):
        good += 1
print('invariant fuzz: %d/%d documents exercised' % (good, trials))
sys.exit(c.done('invariant fuzz'))
