def build_diagnostic(queries, profiles, query_ids, profile_ids, projection):
    signatures = {}
    for pid in profile_ids:
        signature = tuple(projection[(qid, pid)] for qid in query_ids)
        signatures.setdefault(signature, []).append(pid)
    equivalence = sorted(sorted(members) for members in signatures.values())

    requirements = []
    for index, first in enumerate(profile_ids):
        for second in profile_ids[index + 1:]:
            different = frozenset(
                qid for qid in query_ids
                if projection[(qid, first)] != projection[(qid, second)])
            if different and different not in requirements:
                requirements.append(different)
    if not requirements:
        return equivalence, [], 0, 0

    total = len(requirements)
    useful = []
    for qid in query_ids:
        mask = 0
        for position, required in enumerate(requirements):
            if qid in required:
                mask |= 1 << position
        if mask:
            useful.append((mask, queries[qid].cost, qid))

    # A query is never needed when a no-more-expensive query covers a
    # superset of the pairs it distinguishes.
    useful.sort(key=lambda item: (item[1], item[2]))
    candidates = []
    for mask, cost, qid in useful:
        if not any(mask & ~kept[0] == 0 for kept in candidates):
            candidates.append((mask, cost, qid))

    best = minimum_basis(candidates, total)
    basis = sorted(candidates[index][2]
                   for index in range(len(candidates)) if best >> index & 1)
    cost = sum(queries[qid].cost for qid in basis)
    return equivalence, basis, cost, len(basis)


def minimum_basis(candidates, total):
    """Exact optimum: least total cost, then fewest queries.

    ``total`` requirements are encoded as bits; a query is a mask over them
    and a basis must cover every bit.  The exhaustive subset dynamic program
    is bounded by 2**20 states because at most 20 queries exist.
    """
    full = (1 << total) - 1
    masks = [item[0] for item in candidates]
    costs = [item[1] for item in candidates]
    size = 1 << len(candidates)
    covered = [0] * size
    spent = [0] * size
    best_cost = 0
    best_count = 0
    best_mask = 0
    found = False
    for subset in range(1, size):
        low = subset & -subset
        index = low.bit_length() - 1
        previous = subset ^ low
        mask = covered[previous] | masks[index]
        covered[subset] = mask
        cost = spent[previous] + costs[index]
        spent[subset] = cost
        if mask == full:
            count = subset.bit_count()
            if (not found or cost < best_cost or
                    (cost == best_cost and
                     (count < best_count or
                      (count == best_count and subset < best_mask)))):
                found = True
                best_cost = cost
                best_count = count
                best_mask = subset
    if not found:
        # Cannot happen: the candidate set always covers every requirement.
        return (1 << len(candidates)) - 1
    return best_mask


